const state=(c,write=false)=>write?(c.automationEconomy??={}):c.automationEconomy||{},list=(c,key)=>state(c)[key]||[],push=(c,key,value)=>{const s=state(c,true);(s[key]??=[]).push(value);return value;},member=(c,g)=>c.members?.some(m=>m.gangId===g.id),live=g=>!g.remoteReadOnly&&(!g.remoteOwnerId||g.remoteOwnerId===window.AccountParity?.account?.id);

function gangKey(c,g){const m=(c.members||[]).find(m=>m.gangId===g.id||g.sourceGangId&&m.sourceGangId===g.sourceGangId||m.sourceGangId===g.id);return m?.enrollmentRequestId?'enrolled-'+m.enrollmentRequestId:g.remoteSnapshotId||g.id;}
