function supported(c){return String(c.edition).toUpperCase()==='N26'&&(c.campaignTypeId==='official-003-campaign-necromunda-campaign'||!c.campaignTypeId&&c.campaignType==='Necromunda Campaign');}
function requireSupported(c){if(!supported(c))throw Error(T('This framework has no verified automatic economy.','이 캠페인은 수입을 자동으로 계산할 수 없습니다. 적용할 규칙을 확인해 주세요.'));}
