function generateTactics(g,count,die=n=>A().die(n)){const catalog=(R().tactics||[]).filter(t=>t.source_verified&&t.d66_min&&String(t.edition_slug||t.edition).toLowerCase()==='n26'),owned=new Set(ownedTactics(g).map(x=>x.id)),chosen=[],rolls=[];for(let n=0;n<count;n++){if(catalog.every(x=>owned.has(x.id)))break;let row,attempt=0;do{if(++attempt>500)throw Error('Duplicate reroll limit reached');const value=die(6)*10+die(6);rolls.push(value);row=catalog.find(x=>value>=x.d66_min&&value<=x.d66_max);}while(!row||owned.has(row.id));owned.add(row.id);chosen.push(row);}return {cards:chosen.map(x=>({...clone(x),id:uid(),catalogId:x.id,presetId:x.id})),rolls};}
