/* Imported explicit promotion records: kind/type='promotion', id, applied/completed=true or appliedAt,
   and fromTypeId/toTypeId (or fromFighterTypeId/toFighterTypeId). Mere edited subtypes do not qualify. */

function awardRecords(c,g){return [...list(c,'tacticsAwards').filter(a=>belongs(c,g,a)).map(a=>({...a,queue:'campaign'})),...(g.campaignTacticsAwards||[]).filter(a=>a.campaignId===cid(c)&&(!a.gangKey||a.gangKey===gangKey(c,g))).map(a=>({...a,queue:'gang'}))];}
function pendingAwards(c,g){const records=awardRecords(c,g),done=new Set(records.filter(a=>a.pending===false).map(a=>a.key)),seen=new Set();return records.filter(a=>a.pending&&!done.has(a.key)&&!seen.has(a.key)&&(seen.add(a.key),true));}
function queueOwnedTacticsAward(c,g,f,kind='recruit',eventId=f.id){const t=model(f);if(!['recruit','promotion'].includes(kind)||!supported(c)||c.phase==='Closed'||!member(c,g)||!live(g)||!t||(g.fighters||[]).find(x=>x.id===f.id)!==f)return null;const roles=t.fighter_subtypes||[],count=kind==='promotion'?roles.includes('Champion')?1:0:roles.includes('Leader')?2:roles.includes('Champion')?1:0;if(!count)return null;const key=kind+':'+f.id+':'+eventId;if(awardRecords(c,g).some(a=>a.key===key))return null;const award={id:uid(),key,eventId,campaignId:cid(c),gangKey:gangKey(c,g),fighterId:f.id,fighterTypeId:t.id,count,kind,pending:true,origin:'roster-event',at:at()};(g.campaignTacticsAwards??=[]).push(award);return award;}

function promotionRecords(c,g){const found=[];for(const f of g.fighters||[]){const current=model(f);if(!current?.fighter_subtypes?.includes('Champion'))continue;for(const record of [...f.promotionHistory||[],...f.advancements||[]]){if(!record.id||!['promotion'].includes(String(record.kind||record.type||'').toLowerCase())||!(record.applied===true||record.completed===true||record.appliedAt))continue;const from=(R().fighterTypes||[]).find(t=>t.source_verified&&t.id===(record.fromTypeId||record.fromFighterTypeId)),to=(R().fighterTypes||[]).find(t=>t.source_verified&&t.id===(record.toTypeId||record.toFighterTypeId));if(!from||!to||to.id!==current.id||!to.fighter_subtypes?.includes('Champion')||from.fighter_subtypes?.some(s=>['Leader','Champion'].includes(s))||from.gang_type_id!==to.gang_type_id)continue;const key='promotion:'+f.id+':'+record.id;if(awardRecords(c,g).some(a=>a.key===key)||found.some(x=>x.fighter.id===f.id&&x.record.id===record.id))continue;found.push({fighter:f,record,from,to});}}return found;}
